import javax.tools.*;import com.sun.source.util.*;import java.nio.file.*;import java.util.*;
public class JavaSyntaxCheck { public static void main(String[] args)throws Exception{var compiler=ToolProvider.getSystemJavaCompiler();var diagnostics=new DiagnosticCollector<JavaFileObject>();try(var fm=compiler.getStandardFileManager(diagnostics,null,java.nio.charset.StandardCharsets.UTF_8)){List<Path> paths;try(var stream=Files.walk(Path.of(args[0]))){paths=stream.filter(p->p.toString().endsWith(".java")).toList();}var task=(JavacTask)compiler.getTask(null,fm,diagnostics,List.of("-proc:none","--release","21"),null,fm.getJavaFileObjectsFromPaths(paths));task.parse();long errors=diagnostics.getDiagnostics().stream().filter(d->d.getKind()==Diagnostic.Kind.ERROR).count();for(var d:diagnostics.getDiagnostics())System.out.println(d);System.out.println("PARSED="+paths.size()+" ERRORS="+errors);if(errors!=0)System.exit(1);}}}